function parseViewState(params: URLSearchParams): {
  status: 'all' | 'todo' | 'in_progress' | 'done'
  order: string
  q: string
} {
  return {
    status: params.get('status') as 'any' ?? DEFAULT_STATUS,
    order: params.get('order') ?? DEFAULT_ORDER,
